namespace ZFrame.View
{
    /// <summary>
    /// The three quality tiers of the pipeline tier matrix (TASK-A-M2-03).
    /// The enum value doubles as the QualitySettings level index: Low=0,
    /// Medium=1, High=2 (the ProjectSettings/QualitySettings.asset levels
    /// generated by PipelineSetup follow exactly this order).
    /// </summary>
    public enum QualityTier
    {
        Low = 0,
        Medium = 1,
        High = 2,

        /// <summary>Sentinel — never a valid tier; used for bounds checks.</summary>
        Count = 3,
    }
}
